def max_points(points):
    n = len(points)
    if n <= 2:
        return n                        # any 2 or fewer points are trivially "on a line"
    max_count = 2
    for i in range(n):
        for j in range(i + 1, n):
            count = 2                     # the pair itself always counts as 2
            for k in range(n):
                if k == i or k == j:
                    continue
                # cross product is zero exactly when i, j, k are collinear, no division needed
                cross = (points[j][0] - points[i][0]) * (points[k][1] - points[i][1]) - \
                        (points[j][1] - points[i][1]) * (points[k][0] - points[i][0])
                if cross == 0:
                    count += 1              # point k lies on the same line as i and j
            max_count = max(max_count, count)
    return max_count


if __name__ == "__main__":
    points = [[1, 1], [2, 2], [3, 3]]
    print(max_points(points))

