import java.util.*;

public class Main {
    int maxPoints(int[][] points) {
        int n = points.length;
        if (n <= 2) {
            return n;                          // any 2 or fewer points are trivially "on a line"
        }
        int maxCount = 2;
        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                int count = 2;                   // the pair itself always counts as 2
                for (int k = 0; k < n; k++) {
                    if (k == i || k == j) {
                        continue;
                    }
                    // cross product is zero exactly when i, j, k are collinear, no division needed
                    long cross = (long) (points[j][0] - points[i][0]) * (points[k][1] - points[i][1])
                               - (long) (points[j][1] - points[i][1]) * (points[k][0] - points[i][0]);
                    if (cross == 0) {
                        count++;                     // point k lies on the same line as i and j
                    }
                }
                maxCount = Math.max(maxCount, count);
            }
        }
        return maxCount;
    }

    public static void main(String[] args) {
        int[][] points = {{1, 1}, {2, 2}, {3, 3}};
        Main solution = new Main();
        System.out.println(solution.maxPoints(points));
    }
}

