import java.util.*;

public class Main {
    int maxPoints(int[][] points) {
        int n = points.length;
        if (n <= 2) {
            return n;
        }
        int maxCount = 1;
        for (int i = 0; i < n; i++) {
            Map<Double, Integer> slopes = new HashMap<>();  // maps a slope value to how many points share it
            int duplicates = 0;
            int localMax = 0;
            for (int j = 0; j < n; j++) {
                if (i == j) {
                    continue;
                }
                int dx = points[j][0] - points[i][0];
                int dy = points[j][1] - points[i][1];
                if (dx == 0 && dy == 0) {
                    duplicates++;                        // the exact same point appears twice
                    continue;
                }
                double slope = dx == 0 ? Double.POSITIVE_INFINITY : (double) dy / dx; // floating point, precision risk
                int updated = slopes.getOrDefault(slope, 0) + 1;
                slopes.put(slope, updated);
                localMax = Math.max(localMax, updated);
            }
            maxCount = Math.max(maxCount, localMax + duplicates + 1);
        }
        return maxCount;
    }

    public static void main(String[] args) {
        int[][] points = {{1, 1}, {2, 2}, {3, 3}};
        Main solution = new Main();
        System.out.println(solution.maxPoints(points));
    }
}

