import java.util.*;

public class Main {
    int gcdHelper(int a, int b) {
        return b == 0 ? a : gcdHelper(b, a % b);
    }

    int maxPoints(int[][] points) {
        int n = points.length;
        if (n <= 2) {
            return n;
        }
        int maxCount = 1;
        for (int i = 0; i < n; i++) {
            Map<String, Integer> slopes = new HashMap<>();  // maps a reduced direction key to how many points share it
            int duplicates = 0;
            int localMax = 0;
            for (int j = 0; j < n; j++) {
                if (i == j) {
                    continue;
                }
                int dx = points[j][0] - points[i][0];
                int dy = points[j][1] - points[i][1];
                if (dx == 0 && dy == 0) {
                    duplicates++;
                    continue;
                }
                int g = gcdHelper(Math.abs(dx), Math.abs(dy));  // reduce the direction to its simplest whole number form
                dx /= g;
                dy /= g;
                if (dx < 0) {
                    dx = -dx;
                    dy = -dy;                                     // normalize sign so opposite directions share one key
                }
                String key = dx + "," + dy;
                int updated = slopes.getOrDefault(key, 0) + 1;
                slopes.put(key, updated);
                localMax = Math.max(localMax, updated);
            }
            maxCount = Math.max(maxCount, localMax + duplicates + 1);
        }
        return maxCount;
    }

    public static void main(String[] args) {
        int[][] points = {{1, 1}, {2, 2}, {3, 3}};
        Main solution = new Main();
        System.out.println(solution.maxPoints(points));
    }
}

