#include <bits/stdc++.h>
using namespace std;

int gcdHelper(int a, int b) {
    return b == 0 ? a : gcdHelper(b, a % b);
}

int maxPoints(vector<vector<int>>& points) {
    int n = points.size();
    if (n <= 2) {
        return n;
    }
    int maxCount = 1;
    for (int i = 0; i < n; i++) {
        map<pair<int, int>, int> slopes;   // maps a reduced (dx, dy) direction to how many points share it
        int duplicates = 0;
        int localMax = 0;
        for (int j = 0; j < n; j++) {
            if (i == j) {
                continue;
            }
            int dx = points[j][0] - points[i][0];
            int dy = points[j][1] - points[i][1];
            if (dx == 0 && dy == 0) {
                duplicates++;
                continue;
            }
            int g = gcdHelper(abs(dx), abs(dy));  // reduce the direction to its simplest whole number form
            dx /= g;
            dy /= g;
            if (dx < 0) {
                dx = -dx;
                dy = -dy;                            // normalize sign so opposite directions share one key
            }
            localMax = max(localMax, ++slopes[{dx, dy}]);
        }
        maxCount = max(maxCount, localMax + duplicates + 1);
    }
    return maxCount;
}

int main() {
    vector<vector<int>> points = {{1, 1}, {2, 2}, {3, 3}};
    cout << maxPoints(points) << endl;
    return 0;
}
